                  <YAxis
                    type="category"
                    dataKey="shortLabel"
                    width={88}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip formatter={(v: number) => fmtPct(v)} />
                  <Bar dataKey="value" name="Share" radius={[0, 4, 4, 0]}>
