                  />
                  <YAxis
                    type="category"
                    dataKey="shortLabel"
                    width={80}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v: number) =>
                      gapMetric === "gapBn" ? fmtBn(v) : fmtPct(v, 1)
